create_external_database.code:
const response = await client.externalDatabases.createExternalDatabase({
    external_database: {
        name: 'acmedb',
        tables: [
            {
                table_name: 'contacts',
                fields: ['company'],
                records: [{record: [{field: 'company', value: 'Acme Pty Ltd'}]}],
            },
        ],
    },
});
console.log(response.data);

create_external_database_insert_record.code:
const response = await client.externalDatabases.createExternalDatabaseInsertRecord('acmedb', {
    table_name: 'contacts',
    records: [{record: [{field: 'company', value: 'Example Holdings'}]}],
});
console.log(response.data);

update_external_database_update_records.code:
const response = await client.externalDatabases.updateExternalDatabaseUpdateRecords('acmedb', {
    table_name: 'contacts',
    update_fields: [{field_name: 'company', field_value: 'Acme Group'}],
    where_condition: {field_name: 'company', operator: '=', field_value: 'Acme Pty Ltd'},
});
console.log(response.data);
